<?php
namespace App\Services;
use App\Models\OrganizationMembership; use App\Models\PayrollLine; use App\Models\PayrollPeriod; use App\Models\Compensation; use App\Models\CompensationAdjustment; use Illuminate\Support\Facades\DB; use Illuminate\Support\Facades\Validator; use Illuminate\Validation\Rule;
class PayrollService
{
    public function __construct(private WorkspaceAccess $access, private AuditRecorder $audit) {}
    public function generate(OrganizationMembership $actor,array $input):PayrollPeriod
    {
        $this->access->authorize($actor,'payroll.prepare'); $data=Validator::make($input,['period'=>['required','date_format:Y-m'],'starts_on'=>['required','date_format:Y-m-d'],'ends_on'=>['required','date_format:Y-m-d','after_or_equal:starts_on']])->validate(); return DB::transaction(function()use($actor,$data){$period=PayrollPeriod::firstOrCreate(['organization_id'=>$actor->organization_id,'period'=>$data['period']],$data+['status'=>'draft']); abort_if($period->status!=='draft',422,'Only draft payroll periods can be generated.'); foreach(OrganizationMembership::where(['organization_id'=>$actor->organization_id,'status'=>'active'])->get() as $member){$comp=Compensation::where('organization_id',$actor->organization_id)->where('membership_id',$member->id)->whereDate('effective_from','<=',$data['ends_on'])->where(fn($q)=>$q->whereNull('effective_to')->orWhereDate('effective_to','>=',$data['starts_on']))->latest('effective_from')->first(); if(!$comp)continue; $adjustments=CompensationAdjustment::where('organization_id',$actor->organization_id)->where('membership_id',$member->id)->whereDate('effective_from','<=',$data['ends_on'])->where(fn($q)=>$q->whereNull('effective_to')->orWhereDate('effective_to','>=',$data['starts_on']))->get(); $adjustment=$adjustments->sum(fn($row)=>(float)$row->amount*($row->kind==='deduction'?-1:1)); $gross=(float)$comp->base_amount; $net=$gross+$adjustment; PayrollLine::updateOrCreate(['payroll_period_id'=>$period->id,'membership_id'=>$member->id],['organization_id'=>$actor->organization_id,'currency'=>$comp->currency,'gross_amount'=>$gross,'adjustment_amount'=>$adjustment,'net_amount'=>$net,'snapshot'=>['base_amount'=>(string)$comp->base_amount,'adjustments'=>$adjustments->map(fn($row)=>['label'=>$row->label,'amount'=>(string)$row->amount,'kind'=>$row->kind])->values()->all(),'effective_from'=>$comp->effective_from->toDateString()]]);} $this->audit->record($actor->organization_id,$actor,'payroll.generated','payroll_period',$period->id); return $period->load('lines');});
    }
    public function approve(OrganizationMembership $actor,PayrollPeriod $period):PayrollPeriod { abort_unless($period->organization_id===$actor->organization_id,404); $this->access->authorize($actor,'payroll.approve'); abort_if($period->status!=='submitted',422,'Payroll must be submitted before approval.'); $period->update(['status'=>'approved']); $this->audit->record($actor->organization_id,$actor,'payroll.approved','payroll_period',$period->id); return $period; }
    public function submit(OrganizationMembership $actor, PayrollPeriod $period): PayrollPeriod { abort_unless($period->organization_id===$actor->organization_id,404); $this->access->authorize($actor,'payroll.prepare'); abort_unless($period->status==='draft',422,'Only draft payroll can be submitted.'); abort_if(!$period->lines()->exists(),422,'Payroll has no generated lines.'); $period->update(['status'=>'submitted']); $this->audit->record($actor->organization_id,$actor,'payroll.submitted','payroll_period',$period->id); return $period; }
    public function recordPayment(OrganizationMembership $actor, PayrollLine $line, array $input): \App\Models\PayrollPayment { abort_unless($line->organization_id===$actor->organization_id,404); $this->access->authorize($actor,'payroll.manage'); abort_unless(in_array($line->period->status,['approved','locked'],true),422,'Payroll must be approved before payments are recorded.'); $data=Validator::make($input,['amount'=>['required','numeric','gt:0'],'paid_on'=>['required','date_format:Y-m-d'],'reference'=>['nullable','string','max:120',Rule::unique('payroll_payments','reference')->where('organization_id',$actor->organization_id)],'proof_path'=>['nullable','string','max:500']])->validate(); $paid=(float)$line->payments()->sum('amount'); abort_if($paid+(float)$data['amount']>(float)$line->net_amount,422,'Payment exceeds the remaining balance.'); $payment=$line->payments()->create(['organization_id'=>$actor->organization_id]+$data); $this->audit->record($actor->organization_id,$actor,'payroll.payment_recorded','payroll_line',$line->id); return $payment; }
    public function returnForCorrection(OrganizationMembership $actor,PayrollPeriod $period,?string $comment=null):PayrollPeriod { abort_unless($period->organization_id===$actor->organization_id,404); $this->access->authorize($actor,'payroll.approve'); abort_unless($period->status==='submitted',422,'Only submitted payroll can be returned.'); $period->update(['status'=>'returned']); DB::table('payroll_reviews')->insert(['organization_id'=>$actor->organization_id,'payroll_period_id'=>$period->id,'reviewer_membership_id'=>$actor->id,'decision'=>'returned','comment'=>$comment,'created_at'=>now()]); $this->audit->record($actor->organization_id,$actor,'payroll.returned','payroll_period',$period->id); return $period; }
    public function lock(OrganizationMembership $actor,PayrollPeriod $period):PayrollPeriod { abort_unless($period->organization_id===$actor->organization_id,404); $this->access->authorize($actor,'payroll.approve'); abort_unless($period->status==='approved',422,'Only approved payroll can be locked.'); $period->update(['status'=>'locked']); $this->audit->record($actor->organization_id,$actor,'payroll.locked','payroll_period',$period->id); return $period; }
}
